import cmath

def solve_quadratic_eqn(a, b, c):
    d = b * b - 4 * a * c
    if d >= 0:
        sqrt_d = d ** 0.5
    else:
        sqrt_d = cmath.sqrt(d)
    x1 = (-b + sqrt_d) / (2 * a)
    x2 = (-b - sqrt_d) / (2 * a)
    return (x1, x2)
